package com.savora.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class Errors { @ExceptionHandler(Exception.class) ResponseEntity<Api<Map<String,String>>> bad(Exception e){return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new Api<>(Map.of("error",e.getMessage()==null?"Request failed":e.getMessage()),"ERROR"));}}
